import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        int n = scanner.nextInt();

        double bestNumerator = 0;
        double bestDenominator = 1;

        for (int i = 1; i <= n; i++) {
            double ratio = x / y;
            double floorValue = Math.floor(ratio * i);
            long ceilValue = (long) Math.ceil(ratio * i);

            if (Math.abs(ratio - floorValue / i) < Math.abs(ratio - bestNumerator / bestDenominator)) {
                bestNumerator = floorValue;
                bestDenominator = i;
            }
            if (Math.abs(ratio - (double) ceilValue / i) < Math.abs(ratio - bestNumerator / bestDenominator)) {
                bestNumerator = ceilValue;
                bestDenominator = i;
            }
        }
        System.out.println((long) bestNumerator + "/" + (long) bestDenominator);
    }
}
